// Typed invoke wrapper. `commands` is generated by tauri-specta into
// bindings.ts on the first debug run of the app; until then this file
// re-exports a hand-maintained shim so `npm run check` works on a fresh
// clone. If the generated shape differs, update the shim — never bypass it.

import { invoke } from '@tauri-apps/api/core';

export interface AppInfo {
  version: string;
  data_dir: string;
  platform: string;
  arch: string;
}

export async function appInfo(): Promise<AppInfo> {
  return invoke<AppInfo>('app_info');
}

// Session commands — land with the agent core in M1. Typed here so the
// store compiles today; the generated bindings.ts replaces this file's
// internals once specta exports the real signatures.
export async function sessionSend(text: string): Promise<void> {
  return invoke<void>('session_send', { text });
}

export async function sessionCancel(): Promise<void> {
  return invoke<void>('session_cancel');
}

export async function sessionRespondPermission(
  requestId: string,
  decision: 'allow' | 'allow_session' | 'deny',
): Promise<void> {
  return invoke<void>('session_respond_permission', { requestId, decision });
}

export async function sessionAnswer(text: string): Promise<void> {
  return invoke<void>('session_answer', { text });
}
